// ══════════════════════════════════════════════════════════
// PROMPT 1 — System. Hier bearbeitest du die Kurationsregeln.
// ══════════════════════════════════════════════════════════
const SYSTEM_PROMPT = `
Du bist Tageskurator für den Inhaber eines Ein-Personen-Betriebs
(B2B-Automation). Du wählst aus seinem Backlog die Aufgaben für HEUTE.

REGELN
1. Maximal 5 Aufgaben. Weniger ist besser als zu viel.
2. Aufwandsbudget: Summe max. 6 h.
   < 15 min = 0,25 | < 1 h = 1 | Halber Tag = 3 | Mehrere Tage = 3
3. Position 1 ist immer ein Quickwin (< 15 min).
4. Aufgaben mit Eintrag im Feld "blockiert" NIE auswählen.
   Stattdessen den Entblocker als eigene Zeile formulieren,
   z. B. "Rückfrage klären und Termin vereinbaren".
5. "Mehrere Tage"-Aufgaben nur als konkreter Teilschritt,
   max. 1 pro Tag. Nicht "Skill 2 fertigstellen", sondern
   "Skill 2: Abschnitt Fehlerbehandlung schreiben".
6. Abhängigkeitskette beachten, nie den späteren Schritt vorziehen.
   Ein Vorgang, der eine Vorleistung braucht, kommt nach der
   Vorleistung — auch wenn er dringender wirkt.
7. Titel = konkrete nächste Aktion, Verb voran, max. 60 Zeichen.
8. Reihenfolge = Abarbeitungsreihenfolge.
9. Stabilität: Aufgaben, die gestern schon auf "Heute" standen
   und noch offen sind, bevorzugt drinlassen. Kein Neuwürfeln.

AUSGABE
Nur JSON, kein Markdown, kein Vorspann:
{"fokus":"ein Satz, worum es heute geht",
 "auswahl":[{"id":"<id aus Input>","titel":"...","warum":"max 8 Wörter"}]}
`.trim();

// ══════════════════════════════════════════════════════════
// PROMPT 2 — User. Wird pro Lauf aus Datum + Backlog gebaut.
// ══════════════════════════════════════════════════════════
function buildUserPrompt(heute, tasks) {
  return [
    'Heutiges Datum: ' + heute,
    '',
    'Offene Aufgaben:',
    JSON.stringify(tasks, null, 1)
  ].join('\n');
}

// ══════════════════════════════════════════════════════════
// Ab hier Logik — normalerweise nichts zu ändern.
// ══════════════════════════════════════════════════════════

// Property-Zugriff, der fehlende Felder verträgt
function pText(props, name) {
  const p = props ? props[name] : null;
  if (!p) return null;
  const arr = p.rich_text || p.title;
  if (!Array.isArray(arr)) return null;
  const s = arr.map(r => (r && r.plain_text) || '').join(' ').trim();
  return s || null;
}

function pSelect(props, name) {
  const p = props ? props[name] : null;
  return (p && p.select && p.select.name) || null;
}

function pDate(props, name) {
  const p = props ? props[name] : null;
  return (p && p.date && p.date.start) || null;
}

const body = ($('Webhook').first().json.body) || {};

const doneText = Array.isArray(body.done)
  ? body.done.join(' ')
  : String(body.done || '');
const doneIds = (doneText.match(/[0-9a-f]{32}/gi) || []).map(s => s.toLowerCase());

const tasks = (($input.first().json.results) || []).map(p => {
  const pr = p.properties || {};
  return {
    id: p.id.replace(/-/g, '').toLowerCase(),
    url: p.url,
    titel: pText(pr, 'Aufgabe') || '(ohne Titel)',
    status: pSelect(pr, 'Status'),
    prio: pSelect(pr, 'Priorität'),
    bereich: pSelect(pr, 'Bereich'),
    aufwand: pSelect(pr, 'Aufwand'),
    faellig: pDate(pr, 'Fällig'),
    blockiert: pText(pr, 'Blockiert durch'),
    notizen: pText(pr, 'Notizen')
  };
}).filter(t => !doneIds.includes(t.id));

const sd = $getWorkflowStaticData('global');
const heute = new Date().toLocaleDateString('sv-SE', { timeZone: 'Europe/Berlin' });
const kurieren = body.force === true || sd.letzteKuration !== heute;
if (kurieren) sd.letzteKuration = heute;

return [{
  json: {
    kurieren,
    heute,
    doneIds,
    anzahlTasks: tasks.length,
    tasks,
    system: SYSTEM_PROMPT,
    userPrompt: buildUserPrompt(heute, tasks)
  }
}];

const prep = $('Vorbereiten').first().json;

// Alle Text-Blöcke einsammeln (thinking-Blöcke haben kein .text)
const raw = ($input.first().json.content || [])
  .filter(c => c.type === 'text')
  .map(c => c.text || '')
  .join('\n');

// JSON aus Fließtext herausschneiden: erste { bis letzte }
function extractJson(s) {
  const fenced = s.match(/```(?:json)?\s*([\s\S]*?)```/);
  const candidate = fenced ? fenced[1] : s;
  const start = candidate.indexOf('{');
  const end = candidate.lastIndexOf('}');
  if (start === -1 || end === -1) return null;
  try {
    return JSON.parse(candidate.slice(start, end + 1));
  } catch (e) {
    return null;
  }
}

let out = extractJson(raw);

if (!out || !Array.isArray(out.auswahl)) {
  const fb = prep.tasks
    .filter(t => !t.blockiert && t.prio === 'Hoch')
    .slice(0, 3);
  out = {
    fokus: 'Fallback: Kuration nicht lesbar, Top-Prioritäten.',
    auswahl: fb.map(t => ({ id: t.id, titel: t.titel, warum: 'Priorität hoch' }))
  };
}

// Nur IDs zulassen, die es wirklich gibt
const gueltig = new Set(prep.tasks.map(t => t.id));
out.auswahl = out.auswahl
  .map(a => ({ ...a, id: String(a.id).replace(/-/g, '').toLowerCase() }))
  .filter(a => gueltig.has(a.id))
  .slice(0, 5);

return [{ json: out }];

const prep = $('Vorbereiten').first().json;
const heute = prep.tasks.filter(t => t.status === 'Heute');
return [{ json: { fokus: 'Liste von heute früh.', auswahl: heute.map(t => ({ id: t.id, titel: t.titel, warum: '' })) } }];

const prep = $('Vorbereiten').first().json;
const sel  = $input.first().json;

const norm = s => String(s).replace(/-/g, '').toLowerCase();
const byId = Object.fromEntries(prep.tasks.map(t => [t.id, t]));

const auswahl    = (sel.auswahl || []).map(a => ({ ...a, id: norm(a.id) }));
const auswahlIds = new Set(auswahl.map(a => a.id));

const updates = [];

// 1. Vom iPhone gemeldete Erledigungen
for (const id of prep.doneIds) {
  updates.push({ page_id: id, status: 'Erledigt', rang: 99 });
}

// 2. Gestrige "Heute", die heute nicht mehr dabei sind -> zurück auf Offen
for (const t of prep.tasks) {
  if (t.status === 'Heute' && !auswahlIds.has(t.id)) {
    updates.push({ page_id: t.id, status: 'Offen', rang: 98 });
  }
}

// 3. Heutige Auswahl
auswahl.forEach((a, i) => {
  const t = byId[a.id] || {};
  updates.push({
    page_id: a.id,
    status:  'Heute',
    rang:    i,
    titel:   a.titel || t.titel,
    warum:   a.warum || '',
    url:     t.url,
    aufwand: t.aufwand,
    bereich: t.bereich,
    fokus:   sel.fokus || ''
  });
});

return updates.map(json => ({ json }));

const upd   = $('Updates bauen').all().map(i => i.json);
const heute = upd
  .filter(u => u.status === 'Heute')
  .sort((a, b) => a.rang - b.rang);

// Eine Zeile pro Aufgabe: Titel ||| URL
const zeilen = heute.map(h => `${h.titel} ||| ${h.url}`).join('\n');

return [{ json: { zeilen } }];
